tool_input.command:
cat > /tmp/test_weekly.mjs << 'EOF'
import { CYCLE, monthlyCents, nextCharge } from './src/cycles.js';

console.log('Testing weekly cycle support:');

// Test 1: Weekly cycle is recognized
console.log('\n1. Weekly cycle constant:', CYCLE.WEEK);

// Test 2: Monthly cost calculation for weekly plan (€12 per week = €52 per month)
const weeklyPlan = { price: 1200, cycle: 'weekly' };
const monthlyCost = monthlyCents(weeklyPlan);
console.log('2. €12/week plan monthly cost:', monthlyCost, '(should be €52.00)');

// Test 3: Next charge for weekly plan
const today = '2026-10-25';
const nextWeeklyCharge = nextCharge({ cycle: 'weekly', since: '2026-10-24' }, today);
console.log('3. Next charge for weekly plan starting 2026-10-24, querying from 2026-10-25:', nextWeeklyCharge, '(should be 2026-10-31)');

// Test 4: CLI accepts --every week
EOF
node /tmp/test_weekly.mjs
